from robot.utils.robottime import timestr_to_secs, secs_to_timestr


def to_seconds(timestr):
    """
    :param string timestr: Time in human readable string, e.g. 5s, 10minutes, 1min 5s, etc.

    :return: Returns the given time as seconds (float).
    :rtype: float
    """
    return timestr_to_secs(timestr)


def to_string(secs):
    """
    :param float secs: Seconds (float).

    :return: Returns the given seconds as a string, e.g. '5 s'
    :rtype: string
    """
    return secs_to_timestr(secs, compact=True)
